INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Cloud-Computing immer mit dem Internet verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Private Clouds können lokal sein"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal ist für Cloud-Computing typisch?', 3, '[{"text": "Skalierbarkeit", "correct": true, "because": "Ressourcen flexibel anpassbar"}, {"text": "Feste Hardware", "correct": false, "because": "Gegenteil ist wahr"}, {"text": "Lokale Installation", "correct": false, "because": "Nicht Cloud-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Modelle gehören zu Cloud-Computing?', 5, '[{"text": "IaaS", "correct": true, "because": "Infrastruktur als Service"}, {"text": "PaaS", "correct": true, "because": "Plattform als Service"}, {"text": "VPN", "correct": false, "because": "Netzwerktechnik"}, {"text": "LAN", "correct": false, "because": "Lokales Netzwerk"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Cloud-Computing spart Hardwarekosten. b) Es ist immer sicherer als lokale Systeme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit ist kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Cloud-Dienstes?', 4, '[{"text": "Sicherheitsstandards", "correct": false, "because": "Schutz essenziell"}, {"text": "Skalierbarkeit", "correct": false, "because": "Kernmerkmal"}, {"text": "Betriebssystem des Clients", "correct": true, "because": "Cloud-unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Cloud-Computing auch für kleine Firmen geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Kosteneffizient und flexibel"}, {"text": "Nein", "correct": false, "because": "Nicht nur Großunternehmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie ist für Cloud-Computing entscheidend?', 3, '[{"text": "Virtualisierung", "correct": true, "because": "Ressourcen effizient nutzen"}, {"text": "Bluetooth", "correct": false, "because": "Kurzreichweite"}, {"text": "USB", "correct": false, "because": "Hardware-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Cloud-Computing?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Ressourcen on-demand"}, {"text": "Kosteneinsparung", "correct": true, "because": "Weniger Eigenhardware"}, {"text": "Höhere lokale Leistung", "correct": false, "because": "Cloud-basiert"}, {"text": "Automatische Updates", "correct": false, "because": "Service-abhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Cloud-Computing nutzt entfernte Server. b) Es ersetzt lokale Netzwerke. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lokale Netze bleiben relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Cloud-Computing?', 4, '[{"text": "Internetverbindung", "correct": false, "because": "Für Public Cloud nötig"}, {"text": "Service-Provider", "correct": false, "because": "Bietet Ressourcen"}, {"text": "Lokale Serverräume", "correct": true, "because": "Cloud ersetzt sie"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Cloud-Computing immer öffentlich?', 2, '[{"text": "Nein", "correct": true, "because": "Private und Hybrid möglich"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken birgt Cloud-Computing?', 4, '[{"text": "Datenverlust", "correct": true, "because": "Provider-abhängig"}, {"text": "Compliance-Probleme", "correct": true, "because": "Gesetzliche Vorgaben"}, {"text": "Langsame Hardware", "correct": false, "because": "Cloud-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Cloud-Computing keine Wartung erfordert. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Provider wartet, Kunde konfiguriert"}, {"text": "Ja", "correct": false, "because": "Teilweise Aufgaben bleiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Cloud-Anbieter?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Schutz der Daten"}, {"text": "Niedrige Latenz", "correct": false, "because": "Wichtig, aber sekundär"}, {"text": "Kosten allein", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SaaS ist ein Cloud-Modell. b) Es benötigt immer lokale Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SaaS ist cloud-basiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dienste fallen unter Cloud-Computing?', 5, '[{"text": "Virtuelle Maschinen", "correct": true, "because": "IaaS-Beispiel"}, {"text": "Entwicklungsplattformen", "correct": true, "because": "PaaS-Beispiel"}, {"text": "Lokale Backups", "correct": false, "because": "Nicht Cloud-spezifisch"}, {"text": "Router-Konfiguration", "correct": false, "because": "Netzwerkaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Cloud-Computing unwichtig?', 3, '[{"text": "Verfügbarkeit", "correct": false, "because": "Kernmerkmal"}, {"text": "Datenintegrität", "correct": false, "because": "Sicherheitsaspekt"}, {"text": "Lokale CPU-Leistung", "correct": true, "because": "Cloud-unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt Cloud-Computing lokale Server komplett?', 3, '[{"text": "Nein", "correct": true, "because": "Hybridlösungen üblich"}, {"text": "Ja", "correct": false, "because": "Nicht immer praktikabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Cloud-Computing auch für Backups genutzt wird?', 2, '[{"text": "Ja", "correct": true, "because": "Häufige Anwendung"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip steht hinter Cloud-Computing?', 4, '[{"text": "Ressourcenpooling", "correct": true, "because": "Effiziente Nutzung"}, {"text": "Statische Zuweisung", "correct": false, "because": "Gegenteil ist wahr"}, {"text": "Manuelle Skalierung", "correct": false, "because": "Automatisierung üblich"}]');
